def _norm(value: str) -> str:
    return "".join(
        c for c in unicodedata.normalize("NFD", value or "")
        if unicodedata.category(c) != "Mn"
    ).lower()


# precomputed normalized index: norm(parroquia) -> (state, municipio)
_INDEX: dict[str, tuple[str, str]] = {}
for _state, _munis in PARROQUIAS.items():
    for _m in _munis:
        for _p in _m["parroquias"]:
            _INDEX.setdefault(_norm(_p), (_state, _m["municipio"]))


def lookup_municipio(parroquia: str) -> tuple[str, str] | None:
    """Map a reported parroquia name to (state, municipio).

    Exact normalized match first; falls back to substring match so
    partial names or slight typos still resolve.
    """
    if not parroquia:
        return None
    key = _norm(parroquia)
    if key in _INDEX:
        return _INDEX[key]
    best: tuple[str, str] | None = None
    best_len = 0
    for name, target in _INDEX.items():
        if len(name) > best_len and name in key:
            best, best_len = target, len(name)
    return best


def parroquias_for_state(state: str) -> list[dict]:
    """Municipio/parroquia lists for a state (empty when uncovered)."""
    return PARROQUIAS.get(state, [])
